```TestSuite
using Xunit;

public class PrescriptionSystemTests
{
    [Fact]
    public void SystemIsSelfContained_NoDataSharedWithThirdParty()
    {
        // Arrange
        var system = new PrescriptionSystem();

        // Act
        var dataShared = system.CheckDataSharedWithThirdParty();

        // Assert
        Assert.False(dataShared);
    }

    [Fact]
    public void OnlyEmailsSentToPatients_WithFullPrescriptionAndInvoice()
    {
        // Arrange
        var system = new PrescriptionSystem();
        var patient = new Patient { Email = "patient@example.com" };
        var prescription = new Prescription { Content = "Medication X", Invoice = "Invoice Y" };

        // Act
        system.SendEmailToPatient(patient, prescription);

        // Assert
        var emailReceived = system.GetEmailReceived();
        Assert.Equal("patient@example.com", emailReceived.To);
        Assert.Contains("Medication X", emailReceived.Body);
        Assert.Contains("Invoice Y", emailReceived.Body);
    }

    [Fact]
    public void InterfaceWithStandardPaymentGatewayAvailable()
    {
        // Arrange
        var system = new PrescriptionSystem();
        var paymentGateway = new PaymentGateway();

        // Act
        system.ConnectToPaymentGateway(paymentGateway);

        // Assert
        Assert.True(system.IsConnectedToPaymentGateway);
    }

    [Fact]
    public void SecurePaymentAcceptanceButtonEnabled()
    {
        // Arrange
        var system = new PrescriptionSystem();

        // Act
        system.EnableSecurePaymentAcceptanceButton();

        // Assert
        Assert.True(system.IsSecurePaymentAcceptanceButtonEnabled);
    }

    [Fact]
    public void SupportBrowsersGoogleChromeMozillaFirefoxSafari()
    {
        // Arrange
        var system = new PrescriptionSystem();

        // Act
        var browser = new Browser { Name = "Google Chrome" };
        system.CheckBrowserSupport(browser);

        // Assert
        Assert.True(system.IsBrowserSupported(browser));
    }

    [Fact]
    public void SupportOperatingSystems()
    {
        // Arrange
        var system = new PrescriptionSystem();
        var operatingSystem = new OperatingSystem { Name = "Windows 10" };

        // Act
        system.CheckOperatingSystemSupport(operatingSystem);

        // Assert
        Assert.True(system.IsOperatingSystemSupported(operatingSystem));
    }
}
